(async () => {
    const errors = [];
    const logs = [];
    const dom = await JSDOM.fromURL('http://localhost:8765/index.html', {
        runScripts: 'dangerously',
        resources: 'usable',
        pretendToBeVisual: true,
    });
    dom.window.addEventListener('error', e => errors.push('ERROR: ' + e.message));
    dom.window.console.error = (...a) => errors.push('console.error: ' + a.join(' '));
    dom.window.console.warn  = (...a) => logs.push('WARN: ' + a.join(' '));
    dom.window.console.log   = (...a) => logs.push('LOG: ' + a.join(' '));

    // Wait for async d3.csv + simulation setup.
    await new Promise(r => setTimeout(r, 2500));

    const doc = dom.window.document;
    const circles = doc.querySelectorAll('#bubble-chart circle.bubble');
    const labels  = doc.querySelectorAll('#bubble-chart text.bubble-label');
    const rows    = doc.querySelectorAll('#stock-table tbody tr');
    const legend  = doc.querySelectorAll('#legend .legend-item');

    console.log('bubbles:', circles.length);
    console.log('labels:', labels.length);
    console.log('table rows:', rows.length);
    console.log('legend items:', legend.length);
    if (rows.length) {
        console.log('sample row:', rows[0].textContent.trim().replace(/\s+/g, ' '));
        console.log('last  row:', rows[rows.length-1].textContent.trim().replace(/\s+/g, ' '));
    }
    // Spot-check that a bubble has been positioned (transform set).
    if (circles.length) {
        const g = circles[0].parentNode;
        console.log('first bubble transform:', g.getAttribute('transform'));
        console.log('first bubble r:', circles[0].getAttribute('r'));
        console.log('first bubble fill:', circles[0].getAttribute('fill'));
    }
    // Count unique sector colors used.
    const colorSet = new Set();
    circles.forEach(c => colorSet.add(c.getAttribute('fill')));
    console.log('unique bubble colors:', colorSet.size);

    if (errors.length) {
        console.log('\n---ERRORS---');
        errors.forEach(e => console.log(e));
    }
    dom.window.close();
})().catch(e => { console.error('FATAL', e); process.exit(1); });
